from abc import ABC, abstractmethod

# Strategy
class PricingStrategy(ABC):
    @abstractmethod
    def price(self, hours: float) -> float: ...

class HourlyPricing(PricingStrategy):
    def price(self, hours): return 40 * hours

class FlatPricing(PricingStrategy):
    def price(self, hours): return 100

# Observer
class Observer(ABC):
    @abstractmethod
    def update(self, event: str): ...

class Subject:
    def __init__(self):
        self._observers: list[Observer] = []
    def subscribe(self, o: Observer):
        self._observers.append(o)
    def notify(self, event: str):
        for o in self._observers:
            o.update(event)

# Factory
def make_pricing(kind: str) -> PricingStrategy:
    return {"hourly": HourlyPricing, "flat": FlatPricing}[kind]()

