import math, threading, time, uuid
from enum import Enum

class SpotType(Enum):
    BIKE = 1
    CAR = 2
    TRUCK = 3

class Spot:
    def __init__(self, spot_id: str, spot_type: SpotType):
        self.id, self.type = spot_id, spot_type

class Ticket:
    def __init__(self, spot: Spot, plate: str):
        self.id, self.spot, self.plate = uuid.uuid4().hex[:8], spot, plate
        self.entry_time = time.time()

class HourlyPricing:
    RATES = {SpotType.BIKE: 20, SpotType.CAR: 40, SpotType.TRUCK: 80}
    def price(self, ticket: Ticket, exit_time: float) -> int:
        hours = max(1, math.ceil((exit_time - ticket.entry_time) / 3600))
        return hours * self.RATES[ticket.spot.type]

class ParkingLot:
    def __init__(self, spots: list[Spot], pricing=HourlyPricing()):
        self.free = {t: [s for s in spots if s.type == t] for t in SpotType}
        self.pricing = pricing
        self.lock = threading.Lock()

    def park(self, plate: str, spot_type: SpotType) -> Ticket | None:
        with self.lock:                      # no two gates get the same spot
            if not self.free[spot_type]:
                return None
            spot = self.free[spot_type].pop()
        return Ticket(spot, plate)

    def leave(self, ticket: Ticket) -> int:
        fee = self.pricing.price(ticket, time.time())
        with self.lock:
            self.free[ticket.spot.type].append(ticket.spot)
        return fee

