const SpotType = Object.freeze({ BIKE: 'BIKE', CAR: 'CAR', TRUCK: 'TRUCK' });

class HourlyPricing {
  static RATES = { BIKE: 20, CAR: 40, TRUCK: 80 };
  price(ticket, exitTime) {
    const hours = Math.max(1, Math.ceil((exitTime - ticket.entryTime) / 3_600_000));
    return hours * HourlyPricing.RATES[ticket.spot.type];
  }
}

class ParkingLot {
  constructor(spots, pricing = new HourlyPricing()) {
    this.free = {};
    for (const t of Object.values(SpotType)) this.free[t] = spots.filter((s) => s.type === t);
    this.pricing = pricing;
  }
  // JS is single-threaded per process; in a real multi-gate system the
  // allocation must be atomic in the database (e.g. UPDATE ... WHERE free).
  park(plate, type) {
    const spot = this.free[type].pop();
    return spot ? { id: crypto.randomUUID(), spot, plate, entryTime: Date.now() } : null;
  }
  leave(ticket) {
    const fee = this.pricing.price(ticket, Date.now());
    this.free[ticket.spot.type].push(ticket.spot);
