class State:
    def insert(self, m, amount): print("Not allowed now")
    def select(self, m, code): print("Not allowed now")

class Idle(State):
    def insert(self, m, amount):
        m.balance += amount
        m.state = HasMoney()
    def select(self, m, code):
        print("Insert money first")

class HasMoney(State):
    def insert(self, m, amount):
        m.balance += amount
    def select(self, m, code):
        product, price, count = m.inventory.get(code, (None, 0, 0))
        if count == 0:
            print("Out of stock")
        elif m.balance < price:
            print(f"Need {price - m.balance} more")
        else:
            m.inventory[code] = (product, price, count - 1)
            change, m.balance = m.balance - price, 0
            print(f"Dispensing {product}, change {change}")
            m.state = Idle()

class VendingMachine:
    def __init__(self, inventory):
        self.inventory, self.balance, self.state = inventory, 0, Idle()
    def insert(self, amount): self.state.insert(self, amount)
    def select(self, code): self.state.select(self, code)

vm = VendingMachine({"A1": ("Chips", 25, 3)})
vm.insert(50); vm.select("A1")

