import threading, time
from abc import ABC, abstractmethod
from collections import deque

class RateLimiter(ABC):
    @abstractmethod
    def allow(self) -> bool: ...

class TokenBucket(RateLimiter):
    def __init__(self, capacity: int, refill_per_sec: float, clock=time.monotonic):
        self.capacity, self.rate, self.clock = capacity, refill_per_sec, clock
        self.tokens, self.last = float(capacity), clock()
        self.lock = threading.Lock()

    def allow(self) -> bool:
        with self.lock:                          # check-and-spend must be atomic
            now = self.clock()
            self.tokens = min(self.capacity, self.tokens + (now - self.last) * self.rate)
            self.last = now
            if self.tokens >= 1:
                self.tokens -= 1
                return True
            return False

class SlidingWindowLog(RateLimiter):
    def __init__(self, limit: int, window_sec: float, clock=time.monotonic):
        self.limit, self.window, self.clock = limit, window_sec, clock
        self.hits: deque[float] = deque()
        self.lock = threading.Lock()

    def allow(self) -> bool:
        with self.lock:
            now = self.clock()
            while self.hits and now - self.hits[0] >= self.window:
                self.hits.popleft()              # forget old requests
            if len(self.hits) < self.limit:
                self.hits.append(now)
                return True
            return False

class RateLimiterRegistry:
    """One limiter per client key, created on first use."""
    def __init__(self, factory):
        self.factory, self.limiters = factory, {}
        self.lock = threading.Lock()

    def allow(self, key: str) -> bool:
        with self.lock:
            if key not in self.limiters:
                self.limiters[key] = self.factory()
            limiter = self.limiters[key]
        return limiter.allow()

limits = RateLimiterRegistry(lambda: TokenBucket(capacity=3, refill_per_sec=1))
print([limits.allow("u1") for _ in range(4)])   # [True, True, True, False]

