class TokenBucket {
  constructor(capacity, refillPerSec, clock = () => performance.now() / 1000) {
    Object.assign(this, { capacity, rate: refillPerSec, clock });
    this.tokens = capacity;
    this.last = clock();
  }
  // Node runs this synchronously, so no lock is needed inside one process.
  // Across servers, keep the bucket in Redis and update it atomically (Lua script).
  allow() {
    const now = this.clock();
    this.tokens = Math.min(this.capacity, this.tokens + (now - this.last) * this.rate);
    this.last = now;
    if (this.tokens >= 1) { this.tokens -= 1; return true; }
    return false;
  }
}

class RateLimiterRegistry {
  constructor(factory) { this.factory = factory; this.limiters = new Map(); }
  allow(key) {
    if (!this.limiters.has(key)) this.limiters.set(key, this.factory());
    return this.limiters.get(key).allow();
  }
}

