import threading
from enum import Enum

class Direction(Enum):
    UP = 1
    DOWN = -1
    IDLE = 0

class Elevator:
    def __init__(self, eid: int, floor: int = 0):
        self.id, self.floor, self.direction = eid, floor, Direction.IDLE
        self.up_stops: set[int] = set()
        self.down_stops: set[int] = set()
        self.lock = threading.Lock()

    def add_stop(self, floor: int) -> None:
        with self.lock:
            if floor > self.floor:
                self.up_stops.add(floor)
            elif floor < self.floor:
                self.down_stops.add(floor)
            if self.direction == Direction.IDLE and floor != self.floor:
                self.direction = Direction.UP if floor > self.floor else Direction.DOWN

    def step(self) -> int | None:
        """LOOK: go to the next stop in the current direction, else reverse."""
        with self.lock:
            if self.direction == Direction.UP and not self.up_stops:
                self.direction = Direction.DOWN if self.down_stops else Direction.IDLE
            elif self.direction == Direction.DOWN and not self.down_stops:
                self.direction = Direction.UP if self.up_stops else Direction.IDLE
            if self.direction == Direction.UP:
                self.floor = min(self.up_stops); self.up_stops.remove(self.floor)
            elif self.direction == Direction.DOWN:
                self.floor = max(self.down_stops); self.down_stops.remove(self.floor)
            else:
                return None
            return self.floor                     # doors open here

class NearestElevatorDispatch:
    def choose(self, elevators, floor: int, direction: Direction) -> Elevator:
        def cost(e):
            same_way = e.direction in (direction, Direction.IDLE)
            ahead = (floor - e.floor) * (e.direction.value or 1) >= 0
            return abs(e.floor - floor) + (0 if same_way and ahead else 100)
        return min(elevators, key=cost)

class ElevatorController:
    def __init__(self, n: int, dispatch=NearestElevatorDispatch()):
        self.elevators = [Elevator(i) for i in range(n)]
        self.dispatch = dispatch

    def hall_call(self, floor: int, direction: Direction) -> int:
        e = self.dispatch.choose(self.elevators, floor, direction)
        e.add_stop(floor)
        return e.id

    def car_call(self, eid: int, floor: int) -> None:
        self.elevators[eid].add_stop(floor)

e = Elevator(0, floor=2); e.direction = Direction.UP
for f in (5, 3, 1):
    e.add_stop(f)
print([e.step() for _ in range(4)])   # [3, 5, 1, None]

