const Direction = Object.freeze({ UP: 1, DOWN: -1, IDLE: 0 });

class Elevator {
  constructor(id, floor = 0) {
    Object.assign(this, { id, floor, direction: Direction.IDLE });
    this.up = new Set();
    this.down = new Set();
  }
  addStop(floor) {
    if (floor > this.floor) this.up.add(floor);
    else if (floor < this.floor) this.down.add(floor);
    if (this.direction === Direction.IDLE && floor !== this.floor) {
      this.direction = floor > this.floor ? Direction.UP : Direction.DOWN;
    }
  }
  step() { // LOOK scheduling
    if (this.direction === Direction.UP && !this.up.size) this.direction = this.down.size ? Direction.DOWN : Direction.IDLE;
    else if (this.direction === Direction.DOWN && !this.down.size) this.direction = this.up.size ? Direction.UP : Direction.IDLE;
    if (this.direction === Direction.IDLE) return null;
    const stops = this.direction === Direction.UP ? this.up : this.down;
    this.floor = this.direction === Direction.UP ? Math.min(...stops) : Math.max(...stops);
    stops.delete(this.floor);
    return this.floor;
  }
}

const e = new Elevator(0, 2);
e.direction = Direction.UP;
[5, 3, 1].forEach((f) => e.addStop(f));
console.log([e.step(), e.step(), e.step(), e.step()]); // [3, 5, 1, null]

