import random
from abc import ABC, abstractmethod
from collections import deque

class Dice(ABC):
    @abstractmethod
    def roll(self) -> int: ...

class RandomDice(Dice):
    def __init__(self, faces=6, rng=random.Random()):
        self.faces, self.rng = faces, rng
    def roll(self): return self.rng.randint(1, self.faces)

class FixedDice(Dice):                     # for tests
    def __init__(self, rolls): self.rolls = iter(rolls)
    def roll(self): return next(self.rolls)

class Board:
    def __init__(self, size: int, jumps: dict[int, int]):
        assert all(1 < s < size and 0 < e <= size for s, e in jumps.items())
        self.size, self.jumps = size, jumps    # snakes and ladders are both jumps

    def next_position(self, pos: int, roll: int) -> int:
        target = pos + roll
        if target > self.size:
            return pos                         # must land exactly on the last square
        return self.jumps.get(target, target)

class Game:
    def __init__(self, board: Board, players: list[str], dice: Dice):
        self.board, self.dice = board, dice
        self.turns = deque(players)
        self.position = {p: 0 for p in players}
        self.winner = None

    def play_turn(self) -> str:
        player = self.turns.popleft()
        roll = self.dice.roll()
        self.position[player] = self.board.next_position(self.position[player], roll)
        if self.position[player] == self.board.size:
            self.winner = player
        else:
            self.turns.append(player)
        return f"{player} rolled {roll} → {self.position[player]}"

    def play(self) -> str:
        while not self.winner:
            print(self.play_turn())
        return self.winner

game = Game(Board(20, {3: 12, 17: 5}), ["A", "B"], FixedDice([3, 4, 5, 6, 3]))
for _ in range(5):
    print(game.play_turn())

