const Status = Object.freeze({ AVAILABLE: 'available', LOANED: 'loaned', RESERVED: 'reserved' });
const DAY = 86_400_000;

class PerDayFine {
  constructor(perDay = 10) { this.perDay = perDay; }
  fine(due, returned) { return Math.max(0, Math.floor((returned - due) / DAY)) * this.perDay; }
}

class Library {
  static LOAN_DAYS = 14;
  constructor(finePolicy = new PerDayFine(), notify = console.log) {
    Object.assign(this, { finePolicy, notify, items: new Map(), loans: new Map() });
  }
  addCopy(item) { this.items.set(item.barcode, { status: Status.AVAILABLE, reservedFor: null, ...item }); }
  borrow(member, barcode, today) {
    const item = this.items.get(barcode);
    if (item.status === Status.LOANED) throw new Error('copy is out');
    if (item.status === Status.RESERVED && item.reservedFor !== member) throw new Error('reserved for someone else');
    Object.assign(item, { status: Status.LOANED, reservedFor: null });
    const loan = { item, member, due: new Date(+today + Library.LOAN_DAYS * DAY) };
    this.loans.set(barcode, loan);
    return loan;
  }
  reserve(member, book) { book.holds.push(member); }
  giveBack(barcode, today) {
    const { item, due } = this.loans.get(barcode);
    this.loans.delete(barcode);
    const fee = this.finePolicy.fine(due, today);
    if (item.book.holds.length) {
      Object.assign(item, { status: Status.RESERVED, reservedFor: item.book.holds.shift() });
      this.notify(`${item.reservedFor}: ${item.book.title} is ready`);
    } else item.status = Status.AVAILABLE;
    return fee;
  }
}

