import threading, time, uuid
from enum import Enum

class SeatStatus(Enum):
    AVAILABLE = 1
    LOCKED = 2
    BOOKED = 3

class ShowSeat:
    def __init__(self, seat_id: str, price: int):
        self.seat_id, self.price = seat_id, price
        self.status, self.holder, self.hold_until = SeatStatus.AVAILABLE, None, 0.0

    def is_free(self, now: float) -> bool:
        return self.status == SeatStatus.AVAILABLE or (
            self.status == SeatStatus.LOCKED and now >= self.hold_until)   # expired hold

class Show:
    HOLD_SECONDS = 300

    def __init__(self, show_id: str, seats: dict[str, int], clock=time.time):
        self.id, self.clock = show_id, clock
        self.seats = {s: ShowSeat(s, p) for s, p in seats.items()}
        self.lock = threading.Lock()

    def hold(self, user: str, seat_ids: list[str]) -> str:
        with self.lock:                                   # all-or-nothing, atomic
            now = self.clock()
            chosen = [self.seats[s] for s in seat_ids]
            if not all(s.is_free(now) for s in chosen):
                raise ValueError('some seats are no longer available')
            for s in chosen:
                s.status, s.holder, s.hold_until = SeatStatus.LOCKED, user, now + self.HOLD_SECONDS
        return uuid.uuid4().hex[:8]                        # booking id

    def confirm(self, user: str, seat_ids: list[str], pay) -> int:
        total = sum(self.seats[s].price for s in seat_ids)
        with self.lock:
            now = self.clock()
            for s in seat_ids:
                seat = self.seats[s]
                if seat.status != SeatStatus.LOCKED or seat.holder != user or now >= seat.hold_until:
                    raise ValueError('hold expired')
        if not pay(user, total):                           # call the gateway outside the lock
            raise ValueError('payment failed')
        with self.lock:
            for s in seat_ids:
                self.seats[s].status = SeatStatus.BOOKED
        return total

