// In production the hold is one atomic SQL statement, so it's safe across servers.
// If the updated row count != number of seats requested → ROLLBACK (all-or-nothing).
const HOLD_SQL = `
  UPDATE show_seats
     SET status = 'LOCKED', holder = $2, hold_until = now() + interval '5 minutes'
   WHERE show_id = $1 AND seat_id = ANY($3)
     AND (status = 'AVAILABLE' OR (status = 'LOCKED' AND hold_until < now()))`;

async function holdSeats(db, showId, userId, seatIds) {
  return db.transaction(async (tx) => {
    const { rowCount } = await tx.query(HOLD_SQL, [showId, userId, seatIds]);
    if (rowCount !== seatIds.length) throw new Error('some seats are no longer available'); // rolls back
    return { bookingId: crypto.randomUUID(), expiresInSec: 300 };
  });
}

async function confirmBooking(db, payments, showId, userId, seatIds, amount, idempotencyKey) {
  await payments.charge({ userId, amount, idempotencyKey }); // safe to retry
  const { rowCount } = await db.query(
    `UPDATE show_seats SET status = 'BOOKED'
      WHERE show_id = $1 AND seat_id = ANY($2) AND holder = $3 AND status = 'LOCKED' AND hold_until > now()`,
    [showId, seatIds, userId],
  );
  if (rowCount !== seatIds.length) await payments.refund({ idempotencyKey }); // hold expired mid-payment
}

