import threading, uuid
from dataclasses import dataclass, field
from datetime import date
from enum import Enum

class ResState(Enum):
    RESERVED = 1
    PICKED_UP = 2
    RETURNED = 3
    CANCELLED = 4

@dataclass
class Vehicle:
    plate: str
    kind: str            # 'hatchback', 'sedan', 'suv'
    branch: str

@dataclass
class Reservation:
    vehicle: Vehicle
    customer: str
    start: date
    end: date            # exclusive
    state: ResState = ResState.RESERVED
    id: str = field(default_factory=lambda: uuid.uuid4().hex[:8])

def overlaps(a_start, a_end, b_start, b_end) -> bool:
    return a_start < b_end and b_start < a_end

class DailyPricing:
    RATES = {'hatchback': 1500, 'sedan': 2200, 'suv': 3200}
    def price(self, r: Reservation) -> int:
        return (r.end - r.start).days * self.RATES[r.vehicle.kind]

class RentalSystem:
    def __init__(self, vehicles: list[Vehicle], pricing=DailyPricing()):
        self.vehicles, self.pricing = vehicles, pricing
        self.reservations: list[Reservation] = []
        self.lock = threading.Lock()

    def _is_free(self, v: Vehicle, start: date, end: date) -> bool:
        return not any(r.vehicle is v and r.state in (ResState.RESERVED, ResState.PICKED_UP)
                       and overlaps(r.start, r.end, start, end) for r in self.reservations)

    def search(self, branch: str, kind: str, start: date, end: date) -> list[Vehicle]:
        return [v for v in self.vehicles
                if v.branch == branch and v.kind == kind and self._is_free(v, start, end)]

    def reserve(self, customer: str, plate: str, start: date, end: date) -> Reservation:
        if start >= end:
            raise ValueError('end must be after start')
        with self.lock:                     # check + insert must be atomic
            v = next(v for v in self.vehicles if v.plate == plate)
            if not self._is_free(v, start, end):
                raise ValueError('car is booked for those dates')
            r = Reservation(v, customer, start, end)
            self.reservations.append(r)
        return r

    def pick_up(self, r: Reservation):
        assert r.state == ResState.RESERVED
        r.state = ResState.PICKED_UP

    def return_car(self, r: Reservation) -> int:
        assert r.state == ResState.PICKED_UP
        r.state = ResState.RETURNED
        return self.pricing.price(r)

system = RentalSystem([Vehicle('KA-01', 'sedan', 'BLR'), Vehicle('KA-02', 'sedan', 'BLR')])
system.reserve('ravi', 'KA-01', date(2026, 1, 11), date(2026, 1, 14))
print([v.plate for v in system.search('BLR', 'sedan', date(2026, 1, 10), date(2026, 1, 12))])  # ['KA-02']

