const overlaps = (aStart, aEnd, bStart, bEnd) => aStart < bEnd && bStart < aEnd;
const ACTIVE = new Set(['RESERVED', 'PICKED_UP']);

class RentalSystem {
  constructor(vehicles, pricing) { Object.assign(this, { vehicles, pricing, reservations: [] }); }
  isFree(plate, start, end) {
    return !this.reservations.some((r) => r.plate === plate && ACTIVE.has(r.state) && overlaps(r.start, r.end, start, end));
  }
  search(branch, kind, start, end) {
    return this.vehicles.filter((v) => v.branch === branch && v.kind === kind && this.isFree(v.plate, start, end));
  }
  reserve(customer, plate, start, end) {
    if (start >= end) throw new Error('end must be after start');
    if (!this.isFree(plate, start, end)) throw new Error('car is booked for those dates');
    const r = { id: crypto.randomUUID(), customer, plate, start, end, state: 'RESERVED' };
    this.reservations.push(r);
    return r;
  }
}

